#!/usr/bin/env python3
"""Patch the Android files generated by `flutter create` for Rafiq.

- Injects RECORD_AUDIO and MODIFY_AUDIO_SETTINGS permissions before <application>.
- Adds android:largeHeap="true" to the <application> tag.
- Raises minSdk to at least 24 and compileSdk to at least 35 (never lowers them),
  in both build.gradle.kts and build.gradle.

The script is idempotent: running it twice changes nothing the second time.
"""

import pathlib
import re
import sys

MANIFEST = pathlib.Path("android/app/src/main/AndroidManifest.xml")
GRADLE_FILES = (
    pathlib.Path("android/app/build.gradle.kts"),
    pathlib.Path("android/app/build.gradle"),
)

PERMISSIONS = (
    "android.permission.RECORD_AUDIO",
    "android.permission.MODIFY_AUDIO_SETTINGS",
)

MIN_SDK = 24
COMPILE_SDK = 35


def patch_manifest(text: str) -> str:
    # 1) permissions, placed right before the <application> tag
    app_match = re.search(r"^([ \t]*)<application\b", text, re.MULTILINE)
    if app_match is None:
        raise RuntimeError("<application> tag not found in AndroidManifest.xml")
    indent = app_match.group(1)
    missing = [p for p in PERMISSIONS if p not in text]
    if missing:
        block = "".join(
            '{0}<uses-permission android:name="{1}" />\n'.format(indent, p)
            for p in missing
        )
        text = text[: app_match.start()] + block + text[app_match.start():]

    # 2) largeHeap on the <application> tag
    tag_match = re.search(r"<application\b[^>]*>", text, re.DOTALL)
    if tag_match is None:
        raise RuntimeError("<application> tag not found after permission injection")
    tag = tag_match.group(0)
    if "android:largeHeap" not in tag:
        new_tag = tag.replace("<application", '<application android:largeHeap="true"', 1)
        text = text[: tag_match.start()] + new_tag + text[tag_match.end():]
    return text


def _raise_number(match, minimum):
    value = int(match.group("num"))
    return match.group("head") + str(max(value, minimum)) + match.group("tail")


def patch_gradle(text: str, is_kts: bool):
    """Returns (new_text, list_of_changes)."""
    changes = []

    def sub(pattern, repl, label):
        nonlocal text
        new_text, count = re.subn(pattern, repl, text)
        if count:
            changes.append(label)
            text = new_text

    if is_kts:
        sub(r"minSdk\s*=\s*flutter\.minSdkVersion",
            "minSdk = maxOf(flutter.minSdkVersion, {0})".format(MIN_SDK),
            "minSdk (flutter.minSdkVersion -> >= {0})".format(MIN_SDK))
        sub(r"compileSdk\s*=\s*flutter\.compileSdkVersion",
            "compileSdk = maxOf(flutter.compileSdkVersion, {0})".format(COMPILE_SDK),
            "compileSdk (flutter.compileSdkVersion -> >= {0})".format(COMPILE_SDK))
        sub(r"minSdkVersion\s*=\s*flutter\.minSdkVersion",
            "minSdkVersion = maxOf(flutter.minSdkVersion, {0})".format(MIN_SDK),
            "minSdkVersion (kts)")
        sub(r"compileSdkVersion\s*=\s*flutter\.compileSdkVersion",
            "compileSdkVersion = maxOf(flutter.compileSdkVersion, {0})".format(COMPILE_SDK),
            "compileSdkVersion (kts)")
        pat_min = r"(?P<head>\bminSdk(?:Version)?\s*=\s*)(?P<num>\d+)(?P<tail>)"
        pat_compile = r"(?P<head>\bcompileSdk(?:Version)?\s*=\s*)(?P<num>\d+)(?P<tail>)"
    else:
        sub(r"minSdkVersion\s+flutter\.minSdkVersion",
            "minSdkVersion Math.max(flutter.minSdkVersion, {0})".format(MIN_SDK),
            "minSdkVersion (flutter.minSdkVersion -> >= {0})".format(MIN_SDK))
        sub(r"compileSdkVersion\s+flutter\.compileSdkVersion",
            "compileSdkVersion Math.max(flutter.compileSdkVersion, {0})".format(COMPILE_SDK),
            "compileSdkVersion (flutter.compileSdkVersion -> >= {0})".format(COMPILE_SDK))
        sub(r"minSdk\s+flutter\.minSdkVersion",
            "minSdk Math.max(flutter.minSdkVersion, {0})".format(MIN_SDK),
            "minSdk (groovy)")
        sub(r"compileSdk\s+flutter\.compileSdkVersion",
            "compileSdk Math.max(flutter.compileSdkVersion, {0})".format(COMPILE_SDK),
            "compileSdk (groovy)")
        pat_min = r"(?P<head>\bminSdk(?:Version)?[ \t]+)(?P<num>\d+)(?P<tail>)"
        pat_compile = r"(?P<head>\bcompileSdk(?:Version)?[ \t]+)(?P<num>\d+)(?P<tail>)"

    # literal numbers: raise only when lower than the target
    before = text
    text = re.sub(pat_min, lambda m: _raise_number(m, MIN_SDK), text)
    text = re.sub(pat_compile, lambda m: _raise_number(m, COMPILE_SDK), text)
    if text != before:
        changes.append("numeric minSdk/compileSdk raised")
    return text, changes


def main() -> int:
    if not MANIFEST.exists():
        print("::error::{0} not found. Did `flutter create` run?".format(MANIFEST))
        return 1

    original = MANIFEST.read_text(encoding="utf-8")
    patched = patch_manifest(original)
    if patched != original:
        MANIFEST.write_text(patched, encoding="utf-8")
        print("Manifest patched: permissions + largeHeap")
    else:
        print("Manifest already patched")

    found_gradle = False
    for path in GRADLE_FILES:
        if not path.exists():
            continue
        found_gradle = True
        text = path.read_text(encoding="utf-8")
        new_text, changes = patch_gradle(text, path.suffix == ".kts")
        if new_text != text:
            path.write_text(new_text, encoding="utf-8")
            print("{0} patched: {1}".format(path, "; ".join(changes)))
        else:
            print("{0}: no change needed".format(path))

    if not found_gradle:
        print("::warning::No android/app/build.gradle(.kts) found; SDK levels were not touched")
    return 0


if __name__ == "__main__":
    sys.exit(main())
